import{_ as e,o as a,c as s,a2 as o}from"./chunks/framework.Bg-Zxr5O.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/One-Sample-Mode.md","filePath":"manual-en/One-Sample-Mode.md","lastUpdated":1785684581000}'),d={name:"manual-en/One-Sample-Mode.md"};function n(i,t,h,l,r,p){return a(),s("div",null,[...t[0]||(t[0]=[o('<h4 id="_15-13-1-one-sample-mode" tabindex="-1">15.13.1 One Sample Mode <a class="header-anchor" href="#_15-13-1-one-sample-mode" aria-label="Permalink to &quot;15.13.1 One Sample Mode&quot;">​</a></h4><p>The <code>TESTVAL</code> subcommand invokes the One Sample mode. This mode is used to test a population mean against a hypothesized mean. The value given to the <code>TESTVAL</code> subcommand is the value against which you wish to test. In this mode, you must also use the <code>/VARIABLES</code> subcommand to tell PSPP which variables you wish to test.</p><h4 id="_15-13-1-1-example-one-sample-t-test" tabindex="-1">15.13.1.1 Example - One-Sample T-test <a class="header-anchor" href="#_15-13-1-1-example-one-sample-t-test" aria-label="Permalink to &quot;15.13.1.1 Example - One-Sample T-test&quot;">​</a></h4><p>A researcher wishes to know whether the weight of persons in a population is different from the national average. The samples are drawn from the population under investigation and recorded in the file physiology.sav. From the Department of Health, she knows that the national average weight of healthy adults is 76.8kg. Accordingly the <code>TESTVAL</code> is set to 76.8. The null hypothesis therefore is that the mean average weight of the population from which the sample was drawn is 76.8kg.</p><p>As previously noted (see <a href="./Identifying-incorrect-data">Identifying incorrect data</a>), one sample in the dataset contains a weight value which is clearly incorrect. So this is excluded from the analysis using the <code>SELECT</code> command.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>get file=&#39;physiology.sav&#39;.  select if (weight &gt; 0).  t-test testval = 76.8 	/variables = weight.</span></span></code></pre></div><p><strong>Example 15.6:</strong> Running a one-sample T-Test after excluding all non-positive values</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span></code></pre></div><p><strong>Screenshot 15.5:</strong> Using the One-Sample T-Test dialog box to test <strong>weight</strong> for a mean of 76.8kg</p><p>Results 15.2 shows that the mean of our sample differs from the test value by -1.40kg. However the significance is very high (0.610). So one cannot reject the null hypothesis, and must conclude there is not enough evidence to suggest that the mean weight of the persons in our population is different from 76.8kg.</p><table tabindex="0"><thead><tr><th></th><th>t</th><th>df</th><th>Sig. (2-tailed)</th><th>Mean Difference</th><th>95% Confidence Interval of the Difference</th><th></th></tr></thead><tbody><tr><td></td><td>N</td><td>Mean</td><td>Std. Deviation</td><td>S.E. Mean</td><td></td><td></td></tr><tr><td>Weight in kilograms</td><td>39</td><td>75.40</td><td>17.08</td><td>2.73</td><td></td><td></td></tr><tr><td></td><td>Test Value = 76.8</td><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td>Lower</td><td>Upper</td><td></td><td></td><td></td><td></td></tr><tr><td>Weight in kilograms</td><td>-.51</td><td>38</td><td>.610</td><td>-1.40</td><td>-6.94</td><td>4.13</td></tr></tbody></table><p><strong>Results 15.2:</strong> The results of a one-sample T-test of <strong>weight</strong> using a test value of 76.8kg</p>',12)])])}const g=e(d,[["render",n]]);export{m as __pageData,g as default};
